<script setup>
import MButton from '../../../components/mds/MButton.vue'; import MEmptyState from '../../../components/mds/MEmptyState.vue'; import MTag from '../../../components/mds/MTag.vue';
defineProps({rows:{type:Array,default:()=>[]},savingField:String,canEdit:Boolean,error:String});const emit=defineEmits(['back','tighten']);
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><div class="mx-auto max-w-[1000px] space-y-4"><header class="flex items-start justify-between gap-4 rounded-lg bg-[var(--mds-bg)] px-5 py-4 shadow-[var(--mds-shadow-card)]"><div><h1 class="text-[20px] font-semibold">Cấu hình hiển thị trường</h1><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Chỉ có thể siết hiển thị; máy chủ không cho công khai trường nhạy cảm.</p></div><MButton variant="secondary" @click="emit('back')">Quay lại</MButton></header><p v-if="error" role="alert" class="rounded-lg bg-[var(--mds-danger-bg)] px-4 py-3 text-[13px] text-[var(--mds-danger)]">{{ error }}</p><section class="overflow-hidden rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]"><MEmptyState v-if="!rows.length" title="Chưa có trường để cấu hình" description="Máy chủ chưa trả dữ liệu cấu hình."/><table v-else class="w-full text-left"><thead class="bg-[var(--mds-bg-page)] text-[12px] text-[var(--mds-text-secondary)]"><tr><th class="px-5 py-3">Trường</th><th class="px-3 py-3">Trạng thái</th><th class="px-5 py-3 text-right">Thao tác</th></tr></thead><tbody class="divide-y divide-[var(--mds-border-light)]"><tr v-for="row in rows" :key="row.field"><td class="px-5 py-3 text-[13px] font-medium">{{ row.field }}</td><td class="px-3 py-3"><MTag :color="row.isPublic===false?'warning':'neutral'">{{ row.status }}</MTag></td><td class="px-5 py-3 text-right"><MButton v-if="canEdit&&row.isPublic!==false" variant="secondary" :loading="savingField===row.field" @click="emit('tighten',row)">Ẩn trường</MButton><span v-else class="text-[13px] text-[var(--mds-text-secondary)]">{{ row.isPublic===false?'Đã ẩn':'Chỉ xem' }}</span></td></tr></tbody></table></section></div></section></template>
